input.command:
databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "CREATE OR REPLACE TABLE workspace.mlpab1c2d52.training AS SELECT * FROM read_files(\"/Volumes/workspace/mlpab1c2d52/skewvol/training_sample.csv\", format => \"csv\", header => true)"
}' 2>&1 | grep -E 'state|error'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "CREATE OR REPLACE TABLE workspace.mlpab1c2d52.serving AS SELECT * FROM read_files(\"/Volumes/workspace/mlpab1c2d52/skewvol/serving_log.csv\", format => \"csv\", header => true)"
}' 2>&1 | grep -E 'state|error'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "SELECT count(*) AS joined, avg(abs(t.f1-s.f1)) AS d1, avg(abs(t.f2-s.f2)) AS d2, avg(abs(t.f3-s.f3)) AS d3, avg(abs(t.f4-s.f4)) AS d4, avg(abs(t.f5-s.f5)) AS d5 FROM workspace.mlpab1c2d52.training t JOIN workspace.mlpab1c2d52.serving s USING (entity_id)"
}' 2>&1 | grep -A30 '"data_array"'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "SELECT avg(s.f2/t.f2) AS mean_ratio, stddev(s.f2/t.f2) AS sd_ratio, avg(s.f2-t.f2) AS mean_diff, stddev(s.f2-t.f2) AS sd_diff, corr(s.f2, t.f2) AS pearson, corr(ln(s.f2), ln(t.f2)) AS log_corr, min(t.f2) AS tmin, max(t.f2) AS tmax, min(s.f2) AS smin, max(s.f2) AS smax FROM workspace.mlpab1c2d52.training t JOIN workspace.mlpab1c2d52.serving s USING (entity_id)"
}' 2>&1 | grep -A30 '"data_array"'

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "8a93fc195da2ceb1",
  "wait_timeout": "50s",
  "statement": "SELECT max(abs(t.f2 - ln(1+s.f2))) AS max_err_log1p FROM workspace.mlpab1c2d52.training t JOIN workspace.mlpab1c2d52.serving s USING (entity_id)"
}' 2>&1 | grep -A8 '"data_array"'

